CREATE TABLE IF NOT EXISTS service_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, target_industries TEXT[] NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS companies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, domain TEXT UNIQUE, industry TEXT, employee_range TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS client_opportunities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, company_id UUID NOT NULL REFERENCES companies(id), service_profile_id UUID REFERENCES service_profiles(id), title TEXT NOT NULL, score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100), status TEXT NOT NULL DEFAULT 'DISCOVERED' CHECK (status IN ('DISCOVERED','QUALIFIED','OUTREACH_READY','CONTACTED','RESPONDED','CONVERTED','DISQUALIFIED')), facts JSONB NOT NULL DEFAULT '[]', inference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS outreach_drafts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_opportunity_id UUID NOT NULL REFERENCES client_opportunities(id) ON DELETE CASCADE, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','APPROVED','SENT')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
